function decodeBase64(data: string): Uint8Array {
  const binary = atob(data);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

export function createHumanBodyGeometry(): THREE.BufferGeometry {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    "position",
    new THREE.BufferAttribute(new Float32Array(decodeBase64(POSITION_DATA).buffer), 3)
  );
  geometry.setAttribute(
    "color",
    new THREE.BufferAttribute(new Uint8Array(decodeBase64(COLOR_DATA)), 4, true)
  );
  geometry.setIndex(
    new THREE.BufferAttribute(new Uint32Array(decodeBase64(INDEX_DATA).buffer), 1)
  );
  return geometry;
}
